"""Embedded static assets for the dependency-free local research website."""

INDEX_HTML = r'''<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Indian Equity Research Platform</title>
  <link rel="stylesheet" href="/styles.css">
</head>
<body>
  <header class="hero">
    <div><p class="eyebrow">OFFLINE RESEARCH WORKBENCH</p><h1>Indian Equity Research Platform</h1>
    <p>Explainable screening and ranking for research—not investment advice.</p></div>
    <span id="dataBadge" class="badge synthetic">SYNTHETIC RESEARCH TEST</span>
  </header>
  <main>
    <section class="panel setup">
      <div class="section-title"><span>01</span><div><h2>Data</h2><p>Choose the fictional sample, canonical research files, or an official NSE snapshot.</p></div></div>
      <div class="grid two">
        <label>Input source<select id="inputSource"><option value="sample">Built-in synthetic sample</option><option value="prepared_real_baseline">Prepared real NIFTY 50 historical dataset</option><option value="upload">Upload canonical research CSV files</option><option value="official_nse_snapshot">Official NSE / NIFTY snapshot files</option></select></label>
        <label>Dataset/source label<input id="sourceLabel" value="Committed fictional research sample" disabled></label>
        <label>Data mode<select id="dataMode" disabled><option value="synthetic_research_test">SYNTHETIC RESEARCH TEST</option><option value="real_current_snapshot">REAL CURRENT SNAPSHOT</option><option value="real_historical_price_research">REAL HISTORICAL PRICE RESEARCH</option><option value="real_historical_point_in_time">REAL HISTORICAL / POINT-IN-TIME</option></select></label>
        <label>Universe<input id="universeLabel" value="Fictional companies committed for automated research tests" disabled></label>
        <label>As-of / ranking date<input id="rankingDate" type="date" value="2026-06-30"></label>
      </div>
      <div id="baselineFiles" class="uploads"><label>Baseline V1 canonical CSV<input id="baselineFile" type="file" accept=".csv,text/csv"></label></div>
      <div id="v2Files" class="uploads hidden"><label>Universe CSV<input id="universeFile" type="file" accept=".csv,text/csv"></label><label>Price history CSV<input id="pricesFile" type="file" accept=".csv,text/csv"></label><label>Fundamentals CSV<input id="fundamentalsFile" type="file" accept=".csv,text/csv"></label></div>
      <div id="snapshotFiles" class="uploads hidden"><label>NIFTY 50 constituent CSV<input id="niftyFile" type="file" accept=".csv,text/csv"></label><label>NSE CM-UDiFF Bhavcopy ZIP<input id="bhavcopyFile" type="file" accept=".zip,application/zip"></label></div>
    </section>

    <section id="methodPanel" class="panel">
      <div class="section-title"><span>02</span><div><h2 id="methodTitle">Method</h2><p id="methodDescription">Both options call the repository's accepted ranking APIs.</p></div></div>
      <div id="methodChoices" class="methods">
        <label class="method selected"><input type="radio" name="method" value="baseline_v1" checked><strong>Baseline V1 / Original Paper signals</strong><small>Four transparent price signals with the documented equal-rank-mean approximation.</small></label>
        <label class="method"><input type="radio" name="method" value="research_v2"><strong>Research V2</strong><small>Point-in-time prices and fundamentals with nine auditable contributions.</small></label>
      </div>
      <button id="runButton" class="primary">Run analysis</button>
      <div id="error" class="error hidden" role="alert"></div>
    </section>

    <section id="snapshotPanel" class="panel hidden">
      <div class="results-head"><div class="section-title"><span>03</span><div><h2>Real Market Snapshot</h2><p id="snapshotSummary"></p></div></div><button id="snapshotExportButton" class="secondary">Export snapshot CSV</button></div>
      <div id="rankingNotice" class="notice"></div>
      <div class="table-wrap"><table><thead><tr><th>Ticker / company</th><th>Industry</th><th>Close</th><th>Daily change</th><th>Volume</th><th>Traded value</th><th>Details</th></tr></thead><tbody id="snapshotRows"></tbody></table></div>
      <div class="details-grid snapshot-details"><article><h3 id="snapshotDetailTitle">Security details</h3><dl id="snapshotDetails"></dl></article><article><h3>Source audit</h3><dl id="snapshotProvenance"></dl><ul id="snapshotWarnings" class="warnings"></ul></article></div>
    </section>

    <section id="resultsPanel" class="panel hidden">
      <div class="results-head"><div class="section-title"><span>03</span><div><h2>Ranked companies</h2><p id="resultSummary"></p></div></div><button id="exportButton" class="secondary">Export CSV</button></div>
      <div class="table-wrap"><table><thead><tr><th data-sort="rank">Rank</th><th data-sort="ticker">Ticker / company</th><th data-sort="sector">Sector</th><th data-sort="status">Eligibility</th><th data-sort="score">Final score</th><th>Why?</th></tr></thead><tbody id="resultRows"></tbody></table></div>
    </section>

    <section id="detailsGrid" class="details-grid hidden">
      <article class="panel"><div class="section-title"><span>04</span><div><h2 id="detailTitle">Company explanation</h2><p>Only values produced by the selected engine are shown.</p></div></div><div id="explanation"></div></article>
      <article class="panel"><div class="section-title"><span>05</span><div><h2>Provenance & warnings</h2><p>Read this context before interpreting a ranking.</p></div></div><dl id="provenance"></dl><ul id="warnings" class="warnings"></ul></article>
    </section>
  </main>
  <footer>Local-only demonstration · No live data retrieval · No investment advice</footer>
  <script src="/app.js"></script>
</body>
</html>'''

STYLES_CSS = r''':root{--ink:#17212b;--muted:#66727f;--line:#dfe5e8;--paper:#fff;--bg:#f3f5f4;--green:#0d6b55;--green2:#e4f2ed;--amber:#946000;--red:#a43a3a;--navy:#17344d}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font-family:Inter,Segoe UI,Arial,sans-serif}.hero{background:var(--navy);color:#fff;padding:36px max(5vw,28px);display:flex;justify-content:space-between;gap:24px;align-items:center}.hero h1{font-size:clamp(28px,4vw,46px);margin:4px 0 8px;letter-spacing:-.035em}.hero p{margin:0;color:#d9e5ec}.eyebrow{font-size:12px!important;letter-spacing:.18em;color:#8fd4c0!important}.badge{font-size:11px;font-weight:800;letter-spacing:.08em;border-radius:999px;padding:10px 14px;white-space:nowrap;background:#e6f3ee;color:#075946}.badge.real{background:#dceaf4;color:#174b70}.badge.history{background:#f4ead2;color:#765000}main{max-width:1220px;margin:28px auto;padding:0 22px}.panel{background:var(--paper);border:1px solid var(--line);border-radius:14px;padding:24px;margin-bottom:20px;box-shadow:0 3px 16px #2030400a}.section-title{display:flex;gap:14px;align-items:flex-start;margin-bottom:20px}.section-title>span{display:grid;place-items:center;background:var(--green2);color:var(--green);border-radius:8px;width:34px;height:34px;font-weight:800}.section-title h2{margin:0 0 5px;font-size:20px}.section-title p{margin:0;color:var(--muted);font-size:14px}.grid{display:grid;gap:16px}.grid.two{grid-template-columns:repeat(2,minmax(0,1fr))}label{font-size:13px;font-weight:650;color:#394552}input,select{display:block;width:100%;margin-top:7px;padding:11px 12px;border:1px solid #cdd6db;border-radius:8px;background:#fff;color:var(--ink)}input:focus,select:focus{outline:3px solid #a8d7c9;border-color:var(--green)}input:disabled,select:disabled{background:#f4f6f6;color:#68747d}.uploads{display:flex;gap:14px;margin-top:16px;padding:16px;background:#f7f9f8;border:1px dashed #cbd6d2;border-radius:10px}.uploads label{flex:1}.hidden{display:none!important}.methods{display:grid;grid-template-columns:1fr 1fr;gap:14px}.method{border:1px solid var(--line);padding:18px;border-radius:11px;cursor:pointer}.method.selected{border-color:var(--green);box-shadow:inset 0 0 0 1px var(--green);background:#f6fbf9}.method input{display:inline;width:auto;margin:0 8px 0 0}.method small{display:block;color:var(--muted);margin:9px 0 0 25px;line-height:1.45}.primary,.secondary{border:0;border-radius:8px;padding:12px 18px;font-weight:750;cursor:pointer}.primary{background:var(--green);color:#fff;margin-top:18px}.primary:disabled{opacity:.55}.secondary{color:var(--green);background:var(--green2)}.error{margin-top:14px;padding:12px;border-left:4px solid var(--red);background:#fff0f0;color:#822}.notice{margin:0 0 18px;padding:13px 15px;border-left:4px solid var(--amber);background:#fff8e8;color:#684900;font-size:13px;line-height:1.5}.results-head{display:flex;justify-content:space-between;align-items:flex-start}.table-wrap{overflow:auto}table{width:100%;border-collapse:collapse;font-size:14px}th{text-align:left;color:var(--muted);font-size:11px;text-transform:uppercase;letter-spacing:.06em;padding:11px;border-bottom:2px solid var(--line);cursor:pointer}td{padding:12px 11px;border-bottom:1px solid #edf0f1}.company{display:block;color:var(--muted);font-size:12px;margin-top:3px}.status{display:inline-block;border-radius:999px;padding:5px 9px;font-size:11px;font-weight:750}.eligible{background:var(--green2);color:var(--green)}.ineligible{background:#f6e5e5;color:#922}.inspect{border:0;background:none;color:var(--green);font-weight:750;cursor:pointer}.details-grid{display:grid;grid-template-columns:1.25fr .75fr;gap:20px}.snapshot-details{margin-top:22px;padding-top:20px;border-top:1px solid var(--line)}.snapshot-details article{min-width:0}.explanation-group{margin-bottom:18px}.explanation-group h3{font-size:13px;text-transform:uppercase;letter-spacing:.06em;color:var(--muted)}.explanation-row{display:flex;justify-content:space-between;gap:20px;padding:7px 0;border-bottom:1px solid #eef1f1;font-size:13px}.explanation-row code{font-family:ui-monospace,Consolas,monospace}dl{display:grid;grid-template-columns:auto 1fr;gap:8px 14px;font-size:13px}dt{font-weight:750}dd{margin:0;color:var(--muted);overflow-wrap:anywhere}.warnings{padding-left:20px;color:#6f4d00;font-size:13px;line-height:1.55}footer{text-align:center;color:var(--muted);font-size:12px;padding:15px 20px 35px}@media(max-width:760px){.hero{align-items:flex-start;flex-direction:column}.grid.two,.methods,.details-grid{grid-template-columns:1fr}.uploads{flex-direction:column}.results-head{gap:12px;flex-direction:column}}'''

APP_JS = r'''const $=id=>document.getElementById(id);let response=null;let snapshotResponse=null;let rows=[];let sort={key:'sector',asc:true};
function method(){return document.querySelector('input[name=method]:checked').value}
function sync(){const m=method(),source=$('inputSource').value,upload=source==='upload',snapshot=source==='official_nse_snapshot',prepared=source==='prepared_real_baseline';$('baselineFiles').classList.toggle('hidden',m!=='baseline_v1'||!upload);$('v2Files').classList.toggle('hidden',m!=='research_v2'||!upload);$('snapshotFiles').classList.toggle('hidden',!snapshot);$('methodChoices').classList.toggle('hidden',snapshot||prepared);['sourceLabel','dataMode','universeLabel'].forEach(id=>$(id).disabled=!upload);$('rankingDate').disabled=snapshot||prepared;$('methodTitle').textContent=snapshot?'Import':'Method';$('methodDescription').textContent=snapshot?'Validate and display the official one-day snapshot without running a ranking model.':prepared?'Run accepted Baseline V1 from the locally cached and validated real-history bundle.':'Both options call the repository\'s accepted ranking APIs.';if(source==='sample'){$('sourceLabel').value='Committed fictional research sample';$('dataMode').value='synthetic_research_test';$('universeLabel').value='Fictional companies committed for automated research tests';$('rankingDate').value='2026-06-30'}else if(snapshot){$('sourceLabel').value='Official supplied NIFTY constituent file + NSE CM-UDiFF Common Bhavcopy Final';$('dataMode').value='real_current_snapshot';$('universeLabel').value='NIFTY 50';$('rankingDate').value=''}else if(prepared){document.querySelector('input[name=method][value=baseline_v1]').checked=true;$('sourceLabel').value='Validated local historical bundle';$('dataMode').value='real_historical_price_research';$('universeLabel').value='Current NIFTY 50';$('rankingDate').value='2026-08-07'}document.querySelectorAll('.method').forEach(x=>x.classList.toggle('selected',x.querySelector('input').checked));$('runButton').textContent=snapshot?'Import snapshot':'Run analysis';badge()}
function badge(){const v=$('dataMode').value,b=$('dataBadge');b.textContent=$('dataMode').selectedOptions[0].text;b.className='badge '+(v==='real_current_snapshot'?'real':v.startsWith('real_historical')?'history':'synthetic')}
async function read(id){const f=$(id).files[0];if(!f)throw new Error(`${$(id).closest('label').childNodes[0].textContent.trim()} is required`);return await f.text()}
async function readBase64(id){const f=$(id).files[0];if(!f)throw new Error($(id).closest('label').childNodes[0].textContent.trim()+' is required');const bytes=new Uint8Array(await f.arrayBuffer());let binary='';for(let i=0;i<bytes.length;i+=32768)binary+=String.fromCharCode(...bytes.subarray(i,i+32768));return{name:f.name,data:btoa(binary)}}
async function payload(){const source=$('inputSource').value,m=method();if(source==='official_nse_snapshot'){const nifty=await readBase64('niftyFile'),bhav=await readBase64('bhavcopyFile');return{input_source:source,files:{nifty_filename:nifty.name,nifty_base64:nifty.data,bhavcopy_filename:bhav.name,bhavcopy_base64:bhav.data}}}if(source==='prepared_real_baseline')return{input_source:source,method:'baseline_v1'};const sample=source==='sample',p={method:m,use_synthetic_sample:sample,source_label:$('sourceLabel').value,data_mode:$('dataMode').value,universe:$('universeLabel').value,ranking_date:$('rankingDate').value};if(!sample)p.files=m==='baseline_v1'?{baseline:await read('baselineFile')}:{universe:await read('universeFile'),prices:await read('pricesFile'),fundamentals:await read('fundamentalsFile')};return p}
function fmt(v){if(v===null||v===undefined)return '—';if(typeof v==='number')return Number.isInteger(v)?String(v):v.toFixed(6);return String(v)}
const inr=new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:2});
const indianNumber=new Intl.NumberFormat('en-IN',{maximumFractionDigits:0});
function money(v){return v===null||v===undefined?'—':inr.format(v)}
function fillDl(id,pairs){const dl=$(id);dl.innerHTML='';pairs.forEach(([k,v])=>{const dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=k;dd.textContent=fmt(v);dl.append(dt,dd)})}
function snapshotDetails(r){$('snapshotDetailTitle').textContent=r.ticker+' · '+r.company;fillDl('snapshotDetails',[['Industry',r.industry],['ISIN',r.isin],['Series',r.series],['Open',money(r.open)],['High',money(r.high)],['Low',money(r.low)],['Previous close',money(r.previous_close)],['Last price',money(r.last_price)],['Transactions',indianNumber.format(r.transaction_count)],['Board lot',r.board_lot_quantity]])}
function renderSnapshot(data){snapshotResponse=data;$('resultsPanel').classList.add('hidden');$('detailsGrid').classList.add('hidden');$('snapshotPanel').classList.remove('hidden');$('dataBadge').textContent=data.provenance.data_mode;$('dataBadge').className='badge real';$('snapshotSummary').textContent=data.provenance.trade_date+' · '+data.provenance.matched_count+' matched · '+data.provenance.missing_count+' missing';$('rankingNotice').textContent=data.ranking_notice;const body=$('snapshotRows');body.innerHTML='';data.snapshot.forEach(r=>{const tr=document.createElement('tr');const values=[r.ticker+' · '+r.company,r.industry,money(r.close),(r.daily_change_pct===null?'—':r.daily_change_pct.toFixed(2)+'%'),indianNumber.format(r.volume),money(r.traded_value)];values.forEach(v=>{const td=document.createElement('td');td.textContent=v;tr.appendChild(td)});const td=document.createElement('td'),button=document.createElement('button');button.className='inspect';button.textContent='Inspect';button.onclick=()=>snapshotDetails(r);td.appendChild(button);tr.appendChild(td);body.appendChild(tr)});fillDl('snapshotProvenance',[['Mode',data.provenance.data_mode],['Trade date',data.provenance.trade_date],['Companies',data.provenance.constituent_count],['Matched',data.provenance.matched_count],['Missing',data.provenance.missing_count],['Duplicate matches',data.provenance.duplicate_match_count],['NIFTY file',data.provenance.nifty_source_filename],['NSE ZIP',data.provenance.nse_source_filename],['Inner CSV',data.provenance.inner_csv_filename],['NIFTY SHA-256',data.provenance.nifty_file_sha256],['NSE ZIP SHA-256',data.provenance.nse_zip_sha256]]);$('snapshotWarnings').innerHTML='';data.provenance.validation_warnings.forEach(w=>{const li=document.createElement('li');li.textContent=w;$('snapshotWarnings').appendChild(li)});if(data.snapshot.length)snapshotDetails(data.snapshot[0]);$('snapshotPanel').scrollIntoView({behavior:'smooth'})}
function render(){const body=$('resultRows');body.innerHTML='';rows.forEach((r,i)=>{const tr=document.createElement('tr');tr.innerHTML=`<td>${fmt(r.rank)}</td><td><strong>${r.ticker}</strong><span class="company">${r.company}</span></td><td>${r.sector}</td><td><span class="status ${r.eligible?'eligible':'ineligible'}">${r.status}</span></td><td>${fmt(r.score)}</td><td><button class="inspect" data-i="${i}">Inspect</button></td>`;body.appendChild(tr)});document.querySelectorAll('.inspect').forEach(b=>b.onclick=()=>details(rows[Number(b.dataset.i)]))}
function details(r){$('detailsGrid').classList.remove('hidden');$('detailTitle').textContent=`${r.ticker} · ${r.company}`;const host=$('explanation');host.innerHTML='';Object.entries(r.explanation).forEach(([group,value])=>{const div=document.createElement('div');div.className='explanation-group';div.innerHTML=`<h3>${group.replaceAll('_',' ')}</h3>`;if(value&&typeof value==='object')Object.entries(value).forEach(([k,v])=>{const line=document.createElement('div');line.className='explanation-row';line.innerHTML=`<span>${k.replaceAll('_',' ')}</span><code>${fmt(v)}</code>`;div.appendChild(line)});else{const p=document.createElement('p');p.textContent=fmt(value);div.appendChild(p)}host.appendChild(div)});$('detailsGrid').scrollIntoView({behavior:'smooth',block:'start'})}
function provenance(p){$('dataBadge').textContent=p.data_mode;const dl=$('provenance');dl.innerHTML='';[['Source',p.source_label],['As of',p.as_of_date],['Method',p.methodology],['Mode',p.data_mode],['Universe',p.universe],['Companies',p.company_count],['Eligible',p.eligible_count],['Excluded',p.ineligible_count]].forEach(([k,v])=>{dl.insertAdjacentHTML('beforeend',`<dt>${k}</dt><dd>${v}</dd>`)});$('warnings').innerHTML=p.warnings.map(w=>`<li>${w}</li>`).join('')}
async function run(){const button=$('runButton'),error=$('error');button.disabled=true;button.textContent='Running…';error.classList.add('hidden');try{const res=await fetch('/api/analyze',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(await payload())});const data=await res.json();if(!res.ok)throw new Error(data.error||'Analysis failed');if(data.mode==='real_snapshot'){renderSnapshot(data);return}response=data;rows=[...data.results];$('resultSummary').textContent=data.provenance.data_mode_key==='real_historical_price_research'?`Universe: NIFTY 50 · As of: 07-Aug-2026 · Real historical price data · Eligible: ${data.provenance.eligible_count} · Excluded: ${data.provenance.ineligible_count} · Method: Baseline V1 / Original Paper signals`:`${data.provenance.eligible_count} eligible · ${data.provenance.ineligible_count} excluded · ${data.provenance.as_of_date}`;$('resultsPanel').classList.remove('hidden');$('detailsGrid').classList.remove('hidden');provenance(data.provenance);render();if(rows.length)details(rows[0]);$('resultsPanel').scrollIntoView({behavior:'smooth'})}catch(e){error.textContent=e.message;error.classList.remove('hidden')}finally{button.disabled=false;button.textContent=$('inputSource').value==='official_nse_snapshot'?'Import snapshot':'Run analysis'}}
$('snapshotExportButton').onclick=()=>{if(!snapshotResponse)return;const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([snapshotResponse.export_csv],{type:'text/csv;charset=utf-8'}));a.download=snapshotResponse.export_filename;a.click();URL.revokeObjectURL(a.href)};document.querySelectorAll('input[name=method]').forEach(x=>x.onchange=sync);$('inputSource').onchange=sync;$('dataMode').onchange=badge;$('runButton').onclick=run;$('exportButton').onclick=()=>{if(!response)return;const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([response.export_csv],{type:'text/csv;charset=utf-8'}));a.download=response.export_filename;a.click();URL.revokeObjectURL(a.href)};document.querySelectorAll('th[data-sort]').forEach(h=>h.onclick=()=>{const k=h.dataset.sort;sort={key:k,asc:sort.key===k?!sort.asc:true};rows.sort((a,b)=>{const x=a[k],y=b[k];if(x==null)return 1;if(y==null)return-1;return(sort.asc?1:-1)*(typeof x==='number'?x-y:String(x).localeCompare(String(y)))});render()});sync();'''
